const input =
  $input.first().json;

const productionManifestId =
  String(
    input.production_manifest_id || ''
  ).trim();

if (!productionManifestId) {
  throw new Error(
    'AGENT-006 BLOCKED (MISSING_PRODUCTION_MANIFEST_ID): AGENT-006 requires production_manifest_id. No reads or writes performed.'
  );
}

// S5-A (ENG-20260926-018): production_manifest_id is authoritative and must be a
// canonical UUID. Malformed input fails closed here, before any database read or write.
// The manifest is never rediscovered by episode_code or any other label.
const S5_UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!S5_UUID_PATTERN.test(productionManifestId)) {
  throw new Error(
    'AGENT-006 BLOCKED (MALFORMED_PRODUCTION_MANIFEST_ID): production_manifest_id must be a UUID. No reads or writes performed.'
  );
}

const now =
  Date.now();

return [
  {
    json: {
      production_manifest_id:
        productionManifestId.toLowerCase(),

      asset_resolution_run_id:
        `A006-${now}`,

      agent_version:
        'agent006-asset-resolution-readiness-manager-v0.1',

      prompt_version:
        'agent006-resolution-rules-v0.1',

      requested_at:
        new Date(now).toISOString()
    }
  }
];

const row =
  $input.first().json;

const request =
  $('00 - Normalize Asset Resolution Request')
    .first()
    .json;

// S5-A (ENG-20260926-018): defence in depth behind the 02 gate. The row must be the
// exact requested manifest (by UUID) and must be APPROVED. Fails closed before any write.
const s5RequestedId =
  String(request.production_manifest_id || '').trim().toLowerCase();

if (
  !row ||
  !s5RequestedId ||
  String(row.id || '').trim().toLowerCase() !== s5RequestedId ||
  String(row.status || '').trim() !== 'APPROVED'
) {
  throw new Error(
    `AGENT-006 BLOCKED (MANIFEST_NOT_APPROVED_OR_NOT_FOUND): production_manifest_id ${s5RequestedId} did not resolve to an APPROVED episode_production_manifests row. No writes performed.`
  );
}

function parseJson(
  value,
  fieldName
) {

  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  if (
    typeof value === 'string'
  ) {

    try {
      return JSON.parse(value);
    }
    catch (error) {
      throw new Error(
        `AGENT-006 could not parse ${fieldName} as JSON.`
      );
    }
  }

  return value;
}

const productionManifest =
  parseJson(
    row.production_manifest ??
    row.manifest_json ??
    row.production_manifest_json ??
    row.readiness_manifest_json,
    'production_manifest'
  );

if (
  !productionManifest ||
  typeof productionManifest !== 'object'
) {

  throw new Error(
    'AGENT-006 found the manifest row but could not locate the production manifest JSON.'
  );
}

const episode =
  productionManifest.episode || {};

const sourceApprovedAssets =
  productionManifest
    .source_approved_assets || {};

const assetInventory =
  Array.isArray(
    productionManifest.asset_inventory
  )
    ? productionManifest.asset_inventory
    : [];

const uniqueTbdDependencies =
  Array.isArray(
    productionManifest
      .unique_tbd_asset_dependencies
  )
    ? productionManifest
        .unique_tbd_asset_dependencies
    : [];

const shotPlans =
  Array.isArray(
    productionManifest.shot_plans
  )
    ? productionManifest.shot_plans
    : [];

return [
  {
    json: {
      production_manifest_id:
        row.id ||
        row.production_manifest_id ||
        request.production_manifest_id,

      production_plan_run_id:
        row.production_plan_run_id ||
        productionManifest
          .production_plan_run_id ||
        null,

      asset_resolution_run_id:
        request.asset_resolution_run_id,

      episode_script_id:
        row.episode_script_id ||
        episode.episode_script_id ||
        null,

      episode_backlog_id:
        episode.episode_backlog_id ||
        null,

      episode_code:
        row.episode_code ||
        episode.episode_code,

      script_version:
        row.script_version ||
        episode.script_version,

      title_working:
        row.title_working ||
        episode.title_working ||
        '',

      production_manifest:
        productionManifest,

      source_approved_assets:
        sourceApprovedAssets,

      asset_inventory:
        assetInventory,

      unique_tbd_asset_dependencies:
        uniqueTbdDependencies,

      shot_plans:
        shotPlans,

      // S5-C (ENG-20260926-018): carry audio TBDs and source provenance forward
      // unchanged. The full manifest is also preserved above as input truth.
      audio_tbd_dependencies:
        Array.isArray(productionManifest.audio_tbd_dependencies)
          ? productionManifest.audio_tbd_dependencies
          : [],

      source_manifest_context: {
        production_manifest_id: row.id,
        manifest_status: row.status,
        manifest_version: productionManifest.manifest_version || null,
        production_plan_run_id:
          row.production_plan_run_id ||
          productionManifest.production_plan_run_id ||
          null,
        episode_backlog_id:
          row.episode_backlog_id ||
          episode.episode_backlog_id ||
          null,
        readiness_state:
          row.readiness_state ??
          productionManifest.readiness_state ??
          null,
        readiness_flags:
          Array.isArray(productionManifest.readiness_flags)
            ? productionManifest.readiness_flags
            : [],
        workload_counts: {
          shot_count: row.shot_count ?? null,
          image_generation_shot_count: row.image_generation_shot_count ?? null,
          video_generation_shot_count: row.video_generation_shot_count ?? null,
          compositor_shot_count: row.compositor_shot_count ?? null
        },
        tbd_counts: {
          unique_tbd_asset_dependency_count:
            productionManifest.unique_tbd_asset_dependency_count ?? null,
          visual_tbd_dependency_count:
            productionManifest.visual_tbd_dependency_count ?? null,
          audio_tbd_dependency_count:
            productionManifest.audio_tbd_dependency_count ?? null,
          audio_tbd_reference_count:
            productionManifest.audio_tbd_reference_count ?? null
        },
        production_optimization:
          productionManifest.production_optimization || null,
        recovery_lineage:
          productionManifest.production_optimization?.recovery_lineage ||
          productionManifest.recovery ||
          null,
        paid_generation_authorised:
          productionManifest.production_optimization?.paid_generation_authorised ??
          null
      },

      agent_version:
        request.agent_version,

      prompt_version:
        request.prompt_version
    }
  }
];

const ctx =
  $('03 - Prepare Resolution Context')
    .first()
    .json;

const manifest =
  ctx.production_manifest;

// S5-B (ENG-20260926-018): governed registry, aligned with Agent-005 S4B.1 (03C).
// 04 reads status=in.(APPROVED,LOCKED). This re-applies the exact status check and
// excludes rows identifiable as development / mock / test. REVIEW and any other status
// never qualify. Registry rows are only read, never changed or promoted.
const S5_GOVERNED_STATUSES = new Set(['APPROVED', 'LOCKED']);

const s5RawRegistryRows =
  $input
    .all()
    .map(item => item.json)
    .filter(
      row =>
        row &&
        typeof row.asset_id === 'string' &&
        row.asset_id.trim()
    );

function isDevelopmentOrMock(row) {
  let meta = row.metadata_json;
  if (typeof meta === 'string') { try { meta = JSON.parse(meta); } catch (e) { meta = {}; } }
  meta = meta && typeof meta === 'object' ? meta : {};
  const aliases = Array.isArray(row.aliases) ? row.aliases.map(a => String(a)) : [];
  return meta.development_mock === true
    || /mock/i.test(String(meta.provider || ''))
    || /^mock:\/\//i.test(String(row.storage_path || ''))
    || /^(TEST|MOCK)[_-]/i.test(String(row.asset_id))
    || aliases.some(a => /^(TEST|MOCK)[_-]/i.test(a));
}

const s5ExcludedRegistryRows = [];

const registryRows =
  s5RawRegistryRows.filter(row => {
    const status = String(row.status ?? '').trim();
    if (!S5_GOVERNED_STATUSES.has(status)) {
      s5ExcludedRegistryRows.push({ asset_id: row.asset_id, status, reason: 'STATUS_NOT_GOVERNED' });
      return false;
    }
    if (isDevelopmentOrMock(row)) {
      s5ExcludedRegistryRows.push({ asset_id: row.asset_id, status, reason: 'DEVELOPMENT_OR_MOCK' });
      return false;
    }
    return true;
  });

const governedRegistrySource = {
  table: 'public.asset_registry',
  access: 'READ_ONLY (04)',
  db_filter: 'status=in.(APPROVED,LOCKED)',
  governed_statuses: ['APPROVED', 'LOCKED'],
  rows_read: s5RawRegistryRows.length,
  governed_count: registryRows.length,
  governed_asset_ids: registryRows.map(row => row.asset_id).sort(),
  excluded_count: s5ExcludedRegistryRows.length,
  excluded: s5ExcludedRegistryRows.slice(0, 100)
};

// S5-D (ENG-20260926-018): the generic Agent-004 inventory labels are placeholders,
// not asset identities, and must never be used as a registry match label.
const S5_GENERIC_LABEL =
  /^agent-004 approved (new|reused) asset$/i;

function s5PrimaryLabel(inventory) {
  const labels =
    Array.isArray(inventory?.labels)
      ? inventory.labels
      : [];
  return labels.find(
    label =>
      label &&
      !S5_GENERIC_LABEL.test(String(label).trim())
  ) || null;
}

// S5.2 (ENG-20260928-020): deterministic shot attribution for APPROVED_REUSE requirements.
// Source of truth: the approved manifest's structured audio placement
// shot_plans[].shot_plan.audio_plan.named_audio_assets (exact normalized asset name).
// Free text (qc_checks, notes, prompts) is never parsed. No shot IDs are hard-coded.
const s52AudioPlacement = new Map();

for (const sp of (Array.isArray(ctx.shot_plans) ? ctx.shot_plans : [])) {
  let plan = sp?.shot_plan;
  if (typeof plan === 'string') { try { plan = JSON.parse(plan); } catch (e) { plan = null; } }
  const shotId = sp?.shot_id;
  const named = plan?.audio_plan?.named_audio_assets;
  if (!shotId || !Array.isArray(named)) continue;
  for (const name of named) {
    const key = normalize(name);
    if (!key) continue;
    if (!s52AudioPlacement.has(key)) s52AudioPlacement.set(key, new Set());
    s52AudioPlacement.get(key).add(String(shotId));
  }
}

const s52AttributionViolations = [];

function s52ReuseShotAttribution(assetId, inventory) {
  const inventoryShots =
    Array.isArray(inventory?.used_in_shots)
      ? [...new Set(inventory.used_in_shots.map(String))].sort()
      : [];
  const planShots =
    [...(s52AudioPlacement.get(normalize(assetId)) || new Set())].sort();

  if (inventoryShots.length === 0) {
    return planShots.length > 0
      ? { shots: planShots, source: 'MANIFEST_AUDIO_PLAN' }
      : { shots: [], source: 'NONE' };
  }

  if (planShots.length === 0) {
    return { shots: inventoryShots, source: 'INVENTORY' };
  }

  if (JSON.stringify(inventoryShots) !== JSON.stringify(planShots)) {
    s52AttributionViolations.push(
      `APPROVED_REUSE::${assetId} inventory used_in_shots [${inventoryShots.join(',')}] != manifest audio_plan.named_audio_assets shots [${planShots.join(',')}]`
    );
  }

  return { shots: inventoryShots, source: 'INVENTORY_VALIDATED_AGAINST_AUDIO_PLAN' };
}

function normalize(value) {

  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ');
}

function toArray(value) {

  if (Array.isArray(value)) {
    return value;
  }

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return [];
  }

  if (
    typeof value === 'string'
  ) {

    try {

      const parsed =
        JSON.parse(value);

      if (
        Array.isArray(parsed)
      ) {
        return parsed;
      }
    }
    catch (error) {
      return [value];
    }
  }

  return [value];
}

function registryTokens(row) {

  const values = [
    row.asset_id,
    row.asset_name,
    ...toArray(row.aliases)
  ];

  return values
    .filter(Boolean)
    .map(normalize);
}

const inventoryById =
  new Map();

for (
  const item of
  ctx.asset_inventory || []
) {

  if (item.asset_id) {
    inventoryById.set(
      item.asset_id,
      item
    );
  }
}

function chooseAssetType(
  inventoryEntry
) {

  const types =
    Array.isArray(
      inventoryEntry?.asset_types
    )
      ? inventoryEntry.asset_types
      : [];

  const useful =
    types.find(
      value =>
        value !==
        'SOURCE_APPROVED_ASSET'
    );

  return (
    useful ||
    types[0] ||
    'UNKNOWN'
  );
}

function findCandidates({
  sourceAssetId,
  label,
  assetType
}) {

  const targetTokens =
    [
      sourceAssetId,
      label
    ]
      .filter(Boolean)
      .map(normalize);

  const exact = [];

  const sameType = [];

  for (
    const row of
    registryRows
  ) {

    const tokens =
      registryTokens(row);

    const isExact =
      targetTokens.some(
        target =>
          tokens.includes(target)
      );

    if (isExact) {
      exact.push(row);
    }

    if (
      assetType &&
      assetType !== 'UNKNOWN' &&
      normalize(row.asset_type) ===
        normalize(assetType)
    ) {
      sameType.push(row);
    }
  }

  const combined =
    [
      ...exact,
      ...sameType
    ];

  const seen =
    new Set();

  const uniqueCombined =
    combined.filter(row => {

      if (
        seen.has(row.asset_id)
      ) {
        return false;
      }

      seen.add(row.asset_id);

      return true;
    });

  return {
    exact:
      exact.slice(0, 10),

    suggested:
      uniqueCombined.slice(0, 20)
  };
}

const requirements = [];

const sourceNewAssets =
  ctx.source_approved_assets
    ?.unique_new_asset_ids || [];

const sourceReusedAssets =
  ctx.source_approved_assets
    ?.unique_reused_asset_ids || [];

// --------------------------------------------------
// Approved NEW assets
// --------------------------------------------------

for (
  const assetId of
  sourceNewAssets
) {

  const inventory =
    inventoryById.get(
      assetId
    ) || {};

  requirements.push({
    requirement_key:
      `APPROVED_NEW::${assetId}`,

    requirement_origin:
      'APPROVED_NEW',

    requirement_type:
      chooseAssetType(
        inventory
      ),

    source_asset_id:
      assetId,

    source_asset_status:
      'NEW_REQUIRED',

    source_label:
      (
        s5PrimaryLabel(inventory) ||
        assetId
      ),

    source_labels:
      inventory.labels || [],

    source_shot_ids:
      inventory.used_in_shots || []
  });
}

// --------------------------------------------------
// Approved REUSE assets
// --------------------------------------------------

for (
  const assetId of
  sourceReusedAssets
) {

  const inventory =
    inventoryById.get(
      assetId
    ) || {};

  const s52Attribution =
    s52ReuseShotAttribution(
      assetId,
      inventory
    );

  requirements.push({
    requirement_key:
      `APPROVED_REUSE::${assetId}`,

    requirement_origin:
      'APPROVED_REUSE',

    requirement_type:
      chooseAssetType(
        inventory
      ),

    source_asset_id:
      assetId,

    source_asset_status:
      'REUSE',

    source_label:
      (
        s5PrimaryLabel(inventory) ||
        assetId
      ),

    source_labels:
      inventory.labels || [],

    source_shot_ids:
      s52Attribution.shots,

    shot_attribution_source:
      s52Attribution.source
  });
}

if (s52AttributionViolations.length > 0) {
  throw new Error(
    `AGENT-006 S5.2_REUSE_SHOT_ATTRIBUTION_CONFLICT (fail closed, no writes; human review required): ${s52AttributionViolations.join(' | ')}`
  );
}

// --------------------------------------------------
// Unique TBD dependencies
// --------------------------------------------------

// S5-C (ENG-20260926-018): visual and audio TBD dependencies are both preserved.
// Audio TBDs (audio_category / shots, no asset_type) previously collapsed into one
// 'TBD::UNKNOWN::Unresolved asset' key with no shots. They now keep their category and
// shots. No canonical ID is ever assigned to a TBD here.
function s5IsAudioDependency(dep) {
  return (
    String(dep?.dependency_type || '').toUpperCase() === 'AUDIO' ||
    (!!dep?.audio_category && !dep?.asset_type)
  );
}

const s5TbdSources = [
  ...(Array.isArray(ctx.unique_tbd_asset_dependencies) ? ctx.unique_tbd_asset_dependencies : []),
  ...(Array.isArray(ctx.audio_tbd_dependencies) ? ctx.audio_tbd_dependencies : [])
];

for (
  const dep of
  s5TbdSources
) {

  if (!dep || typeof dep !== 'object') {
    throw new Error('AGENT-006 S5 found a malformed TBD dependency entry in the approved production manifest.');
  }

  if (s5IsAudioDependency(dep)) {

    const category =
      String(dep.audio_category || '').trim();

    if (!category) {
      throw new Error('AGENT-006 S5 found an audio TBD dependency without audio_category (fail closed; will not collapse audio TBDs).');
    }

    requirements.push({
      requirement_key:
        `TBD::AUDIO::${category}`,

      requirement_origin:
        'TBD_DEPENDENCY',

      requirement_type:
        'AUDIO',

      dependency_class:
        'AUDIO',

      audio_category:
        category,

      source_asset_id:
        null,

      source_asset_status:
        'TBD',

      source_label:
        category,

      source_labels:
        Array.isArray(dep.source_phrases) ? dep.source_phrases : [],

      source_shot_ids:
        Array.isArray(dep.shots)
          ? dep.shots
          : (Array.isArray(dep.affected_shots) ? dep.affected_shots : [])
    });

    continue;
  }

  const assetType =
    dep.asset_type ||
    'UNKNOWN';

  const dependency =
    dep.dependency ||
    'Unresolved asset';

  requirements.push({
    requirement_key:
      `TBD::${assetType}::${dependency}`,

    requirement_origin:
      'TBD_DEPENDENCY',

    requirement_type:
      assetType,

    dependency_class:
      'VISUAL',

    source_asset_id:
      null,

    source_asset_status:
      'TBD',

    source_label:
      dependency,

    source_labels:
      dep.source_labels || [],

    source_shot_ids:
      dep.affected_shots ||
      dep.shots ||
      []
  });
}

// --------------------------------------------------
// Deduplicate requirements
// --------------------------------------------------

const requirementMap =
  new Map();

for (
  const req of
  requirements
) {

  if (
    !requirementMap.has(
      req.requirement_key
    )
  ) {

    requirementMap.set(
      req.requirement_key,
      req
    );
  }

  // S5-C: a repeated key (e.g. an audio TBD listed in both unique_tbd_asset_dependencies
  // and audio_tbd_dependencies) is merged, never silently dropped: shots and labels are unioned.
  else {

    const existing =
      requirementMap.get(
        req.requirement_key
      );

    existing.source_shot_ids =
      [...new Set([
        ...(existing.source_shot_ids || []),
        ...(req.source_shot_ids || [])
      ])].sort();

    existing.source_labels =
      [...new Set([
        ...(existing.source_labels || []),
        ...(req.source_labels || [])
      ])];
  }
}

const uniqueRequirements =
  [...requirementMap.values()];

// S5-C invariants (fail closed): every TBD dependency declared by the approved manifest
// must become exactly one requirement with at least one affected shot.
const s5Manifest =
  ctx.production_manifest || {};

const s5VisualTbd =
  uniqueRequirements.filter(req => req.requirement_origin === 'TBD_DEPENDENCY' && req.dependency_class === 'VISUAL');

const s5AudioTbd =
  uniqueRequirements.filter(req => req.requirement_origin === 'TBD_DEPENDENCY' && req.dependency_class === 'AUDIO');

const s5Violations = [];

if (
  typeof s5Manifest.visual_tbd_dependency_count === 'number' &&
  s5VisualTbd.length !== s5Manifest.visual_tbd_dependency_count
) {
  s5Violations.push(`visual TBD requirements ${s5VisualTbd.length} != manifest visual_tbd_dependency_count ${s5Manifest.visual_tbd_dependency_count}`);
}

if (
  typeof s5Manifest.audio_tbd_dependency_count === 'number' &&
  s5AudioTbd.length !== s5Manifest.audio_tbd_dependency_count
) {
  s5Violations.push(`audio TBD requirements ${s5AudioTbd.length} != manifest audio_tbd_dependency_count ${s5Manifest.audio_tbd_dependency_count}`);
}

for (const dep of (Array.isArray(ctx.audio_tbd_dependencies) ? ctx.audio_tbd_dependencies : [])) {
  const key = `TBD::AUDIO::${String(dep?.audio_category || '').trim()}`;
  if (!requirementMap.has(key)) {
    s5Violations.push(`audio TBD ${key} missing from requirements`);
  }
}

for (const req of [...s5VisualTbd, ...s5AudioTbd]) {
  if (!Array.isArray(req.source_shot_ids) || req.source_shot_ids.length === 0) {
    s5Violations.push(`${req.requirement_key} has no affected shots`);
  }
  if (req.source_asset_id !== null) {
    s5Violations.push(`${req.requirement_key} carries a source_asset_id; TBDs never receive IDs here`);
  }
}

if (s5Violations.length > 0) {
  throw new Error(
    `AGENT-006 S5_REQUIREMENT_INTEGRITY_FAILED (fail closed, no writes): ${s5Violations.join(' | ')}`
  );
}

if (
  uniqueRequirements.length === 0
) {

  throw new Error(
    'AGENT-006 found no asset requirements in the approved production manifest.'
  );
}

// --------------------------------------------------
// Add registry candidates
// --------------------------------------------------

return uniqueRequirements.map(
  (req, index) => {

    const candidates =
      findCandidates({
        sourceAssetId:
          req.source_asset_id,

        label:
          req.source_label,

        assetType:
          req.requirement_type
      });

    return {
      json: {
        production_manifest_id:
          ctx.production_manifest_id,

        production_plan_run_id:
          ctx.production_plan_run_id,

        asset_resolution_run_id:
          ctx.asset_resolution_run_id,

        episode_script_id:
          ctx.episode_script_id,

        episode_code:
          ctx.episode_code,

        script_version:
          ctx.script_version,

        title_working:
          ctx.title_working,

        requirement_index:
          index + 1,

        total_requirements:
          uniqueRequirements.length,

        ...req,

        dependency_class:
          req.dependency_class ||
          (req.requirement_origin === 'TBD_DEPENDENCY' ? 'VISUAL' : 'APPROVED_ASSET'),

        governed_registry_summary: {
          rows_read: governedRegistrySource.rows_read,
          governed_count: governedRegistrySource.governed_count,
          excluded_count: governedRegistrySource.excluded_count
        },

        exact_candidate_assets:
          candidates.exact,

        suggested_candidate_assets:
          candidates.suggested,

        exact_candidate_asset_ids:
          candidates.exact
            .map(
              row =>
                row.asset_id
            ),

        suggested_candidate_asset_ids:
          candidates.suggested
            .map(
              row =>
                row.asset_id
            ),

        agent_version:
          ctx.agent_version,

        prompt_version:
          ctx.prompt_version
      }
    };
  }
);

const item =
  $input.first().json;

const exactCandidates =
  Array.isArray(
    item.exact_candidate_assets
  )
    ? item.exact_candidate_assets
    : [];

const suggestedCandidates =
  Array.isArray(
    item.suggested_candidate_assets
  )
    ? item.suggested_candidate_assets
    : [];

let resolutionStatus;

let canonicalAssetId =
  null;

let resolutionReason =
  '';

let nextAction =
  '';

let creationBrief =
  null;

// --------------------------------------------------
// Helper
// --------------------------------------------------

function candidateIdList(
  candidates
) {

  return candidates.map(
    item =>
      item.asset_id
  );
}

// --------------------------------------------------
// APPROVED REUSE
// --------------------------------------------------

if (
  item.requirement_origin ===
  'APPROVED_REUSE'
) {

  if (
    exactCandidates.length === 1
  ) {

    resolutionStatus =
      'REUSE_EXISTING';

    canonicalAssetId =
      exactCandidates[0]
        .asset_id;

    resolutionReason =
      'The approved reused asset has exactly one approved or locked canonical registry match.';

    nextAction =
      'Reuse the canonical asset in downstream production.';
  }

  else if (
    exactCandidates.length > 1
  ) {

    resolutionStatus =
      'NEEDS_HUMAN_REVIEW';

    resolutionReason =
      'Multiple canonical registry assets match an upstream-approved reused asset. Agent-006 will not choose between them automatically.';

    nextAction =
      'Human must select the correct canonical asset mapping.';
  }

  else {

    resolutionStatus =
      'BLOCKED_MISSING_REUSE';

    resolutionReason =
      'Agent-004/005 requires this asset to be reused, but no approved or locked canonical registry match exists.';

    nextAction =
      'Locate or register the missing approved reusable asset before generation.';
  }
}

// --------------------------------------------------
// APPROVED NEW
// --------------------------------------------------

else if (
  item.requirement_origin ===
  'APPROVED_NEW'
) {

  if (
    exactCandidates.length === 1
  ) {

    resolutionStatus =
      'REUSE_EXISTING';

    canonicalAssetId =
      exactCandidates[0]
        .asset_id;

    resolutionReason =
      'The approved new asset has already been created and mapped into the canonical asset registry.';

    nextAction =
      'Reuse the already-created canonical asset in downstream production.';
  }

  else if (
    exactCandidates.length > 1
  ) {

    resolutionStatus =
      'NEEDS_HUMAN_REVIEW';

    resolutionReason =
      'More than one canonical asset claims the same approved temporary asset identity.';

    nextAction =
      'Human must resolve the duplicate asset mapping.';
  }

  else {

    resolutionStatus =
      'CREATE_NEW';

    resolutionReason =
      'Agent-004 approved this as a new episode asset and no approved canonical asset is currently mapped to it.';

    nextAction =
      'Create the asset, register it in asset_registry, and include the temporary source ID as an alias before rerunning readiness.';

    creationBrief = {
      temporary_asset_id:
        item.source_asset_id,

      asset_type:
        item.requirement_type,

      requested_name:
        item.source_label,

      source_labels:
        item.source_labels || [],

      affected_shots:
        item.source_shot_ids || [],

      constraints: [
        'Preserve the approved Agent-004 and Agent-005 story requirements.',
        'Do not redesign Mikko, Lumi, the episode structure, or the approved action sequence.',
        'After creation, register the finished asset in asset_registry with APPROVED or LOCKED status.',
        'Include the temporary source asset ID in the registry aliases field so Agent-006 can resolve it on the next run.'
      ]
    };
  }
}

// --------------------------------------------------
// TBD DEPENDENCY
// --------------------------------------------------

else if (
  item.requirement_origin ===
  'TBD_DEPENDENCY'
) {

  if (
    exactCandidates.length === 1
  ) {

    resolutionStatus =
      'REUSE_EXISTING';

    canonicalAssetId =
      exactCandidates[0]
        .asset_id;

    resolutionReason =
      'The unresolved dependency has exactly one approved canonical registry match by asset name, ID, or alias.';

    nextAction =
      'Use the matched canonical asset.';
  }

  else {

    resolutionStatus =
      'NEEDS_HUMAN_REVIEW';

    resolutionReason =
      exactCandidates.length > 1
        ? 'Multiple approved canonical assets match this unresolved dependency.'
        : 'No exact approved canonical mapping exists for this unresolved dependency.';

    nextAction =
      suggestedCandidates.length > 0
        ? 'Human should review the suggested same-type canonical assets or approve creation of a new asset.'
        : 'Human must decide whether this dependency should map to an existing asset or become a new asset.';
  }
}

else {

  resolutionStatus =
    'NEEDS_HUMAN_REVIEW';

  resolutionReason =
    'Unknown requirement origin.';

  nextAction =
    'Human review required.';
}

return [
  {
    json: {
      ...item,

      resolution_status:
        resolutionStatus,

      canonical_asset_id:
        canonicalAssetId,

      resolution_reason:
        resolutionReason,

      creation_brief_json:
        creationBrief,

      next_action:
        nextAction,

      exact_candidate_asset_ids:
        candidateIdList(
          exactCandidates
        ),

      suggested_candidate_asset_ids:
        candidateIdList(
          suggestedCandidates
        )
    }
  }
];

const item =
  $input.first().json;

const allowedStatuses =
  new Set([
    'REUSE_EXISTING',
    'CREATE_NEW',
    'NEEDS_HUMAN_REVIEW',
    'BLOCKED_MISSING_REUSE'
  ]);

if (
  !allowedStatuses.has(
    item.resolution_status
  )
) {

  throw new Error(
    `AGENT-006 invalid resolution_status for ${item.requirement_key}: ${item.resolution_status}`
  );
}

if (
  item.resolution_status ===
    'REUSE_EXISTING' &&
  !item.canonical_asset_id
) {

  throw new Error(
    `AGENT-006 resolved ${item.requirement_key} as REUSE_EXISTING without a canonical_asset_id.`
  );
}

if (
  item.resolution_status ===
    'CREATE_NEW' &&
  !item.creation_brief_json
) {

  throw new Error(
    `AGENT-006 marked ${item.requirement_key} CREATE_NEW without a creation brief.`
  );
}

return [
  {
    json: {
      asset_resolution_run_id:
        item.asset_resolution_run_id,

      production_manifest_id:
        item.production_manifest_id,

      production_plan_run_id:
        item.production_plan_run_id,

      episode_script_id:
        item.episode_script_id,

      episode_code:
        item.episode_code,

      script_version:
        item.script_version,

      requirement_index:
        item.requirement_index,

      requirement_key:
        item.requirement_key,

      requirement_origin:
        item.requirement_origin,

      requirement_type:
        item.requirement_type,

      source_asset_id:
        item.source_asset_id,

      source_asset_status:
        item.source_asset_status,

      source_label:
        item.source_label,

      source_shot_ids:
        item.source_shot_ids || [],

      exact_candidate_asset_ids:
        item.exact_candidate_asset_ids || [],

      suggested_candidate_asset_ids:
        item.suggested_candidate_asset_ids || [],

      resolution_status:
        item.resolution_status,

      canonical_asset_id:
        item.canonical_asset_id,

      resolution_reason:
        item.resolution_reason,

      creation_brief_json:
        item.creation_brief_json,

      next_action:
        item.next_action,

      status:
        'REVIEW',

      agent_version:
        item.agent_version,

      prompt_version:
        item.prompt_version
    }
  }
];

const ctx =
  $('03 - Prepare Resolution Context')
    .first()
    .json;

const workItems =
  $('05 - Build Asset Resolution Work Items')
    .all()
    .map(
      item =>
        item.json
    );

const records =
  $input
    .all()
    .map(
      item =>
        item.json
    )
    .filter(
      row =>
        row &&
        row.requirement_key
    );

const expectedCount =
  workItems.length;

const actualCount =
  records.length;

if (
  actualCount !== expectedCount
) {

  throw new Error(
    `AGENT-006 incomplete resolution set. Expected ${expectedCount} requirements but found ${actualCount}.`
  );
}

const expectedKeys =
  new Set(
    workItems.map(
      item =>
        item.requirement_key
    )
  );

const actualKeys =
  new Set(
    records.map(
      item =>
        item.requirement_key
    )
  );

const missingKeys =
  [...expectedKeys]
    .filter(
      key =>
        !actualKeys.has(key)
    );

if (
  missingKeys.length > 0
) {

  throw new Error(
    `AGENT-006 missing requirement records: ${missingKeys.join(', ')}`
  );
}

if (
  actualKeys.size !==
  records.length
) {

  throw new Error(
    'AGENT-006 found duplicate requirement records.'
  );
}

const counts = {
  REUSE_EXISTING: 0,
  CREATE_NEW: 0,
  NEEDS_HUMAN_REVIEW: 0,
  BLOCKED_MISSING_REUSE: 0
};

for (
  const record of
  records
) {

  if (
    counts[
      record.resolution_status
    ] !== undefined
  ) {

    counts[
      record.resolution_status
    ] += 1;
  }
}

records.sort(
  (a, b) =>
    Number(a.requirement_index) -
    Number(b.requirement_index)
);

return [
  {
    json: {
      production_manifest_id:
        ctx.production_manifest_id,

      production_plan_run_id:
        ctx.production_plan_run_id,

      asset_resolution_run_id:
        ctx.asset_resolution_run_id,

      episode_script_id:
        ctx.episode_script_id,

      episode_code:
        ctx.episode_code,

      script_version:
        ctx.script_version,

      title_working:
        ctx.title_working,

      expected_requirement_count:
        expectedCount,

      resolved_requirement_count:
        actualCount,

      resolution_counts:
        counts,

      resolution_records:
        records,

      agent_version:
        ctx.agent_version,

      prompt_version:
        ctx.prompt_version
    }
  }
];

const validated =
  $input.first().json;

// S5-C (ENG-20260926-018): source manifest provenance is carried into the readiness
// manifest unchanged (input truth). Readiness precedence below is unchanged.
const s5Ctx =
  $('03 - Prepare Resolution Context')
    .first()
    .json;

const records =
  validated.resolution_records || [];

const counts =
  validated.resolution_counts || {};

const reuseAssets =
  records.filter(
    item =>
      item.resolution_status ===
      'REUSE_EXISTING'
  );

const createAssets =
  records.filter(
    item =>
      item.resolution_status ===
      'CREATE_NEW'
  );

const humanReview =
  records.filter(
    item =>
      item.resolution_status ===
      'NEEDS_HUMAN_REVIEW'
  );

const blocked =
  records.filter(
    item =>
      item.resolution_status ===
      'BLOCKED_MISSING_REUSE'
  );

// --------------------------------------------------
// Readiness precedence
// --------------------------------------------------

let readinessState;

if (
  blocked.length > 0
) {

  readinessState =
    'BLOCKED';
}

else if (
  humanReview.length > 0
) {

  readinessState =
    'NEEDS_HUMAN_REVIEW';
}

else if (
  createAssets.length > 0
) {

  readinessState =
    'NEEDS_ASSET_CREATION';
}

else {

  readinessState =
    'READY_FOR_HUMAN_APPROVAL';
}

// --------------------------------------------------
// Reuse mapping
// --------------------------------------------------

const canonicalReuseMap =
  reuseAssets.map(
    item => ({
      requirement_key:
        item.requirement_key,

      requirement_type:
        item.requirement_type,

      source_asset_id:
        item.source_asset_id,

      source_label:
        item.source_label,

      canonical_asset_id:
        item.canonical_asset_id,

      affected_shots:
        item.source_shot_ids || []
    })
  );

// --------------------------------------------------
// Creation queue
// --------------------------------------------------

const assetCreationQueue =
  createAssets.map(
    item => ({
      requirement_key:
        item.requirement_key,

      requirement_type:
        item.requirement_type,

      source_asset_id:
        item.source_asset_id,

      source_label:
        item.source_label,

      affected_shots:
        item.source_shot_ids || [],

      creation_brief:
        item.creation_brief_json,

      next_action:
        item.next_action
    })
  );

// --------------------------------------------------
// Human review queue
// --------------------------------------------------

const humanReviewQueue =
  humanReview.map(
    item => ({
      requirement_key:
        item.requirement_key,

      requirement_type:
        item.requirement_type,

      source_label:
        item.source_label,

      affected_shots:
        item.source_shot_ids || [],

      exact_candidate_asset_ids:
        item.exact_candidate_asset_ids || [],

      suggested_candidate_asset_ids:
        item.suggested_candidate_asset_ids || [],

      reason:
        item.resolution_reason,

      next_action:
        item.next_action
    })
  );

// --------------------------------------------------
// Blocked queue
// --------------------------------------------------

const blockedRequirements =
  blocked.map(
    item => ({
      requirement_key:
        item.requirement_key,

      requirement_type:
        item.requirement_type,

      source_asset_id:
        item.source_asset_id,

      source_label:
        item.source_label,

      reason:
        item.resolution_reason,

      next_action:
        item.next_action
    })
  );

// --------------------------------------------------
// Manifest
// --------------------------------------------------

const readinessManifest = {

  manifest_version:
    'agent006-production-readiness-v0.1',

  asset_resolution_run_id:
    validated.asset_resolution_run_id,

  source_production_manifest_id:
    validated.production_manifest_id,

  source_production_plan_run_id:
    validated.production_plan_run_id,

  episode: {
    episode_script_id:
      validated.episode_script_id,

    episode_code:
      validated.episode_code,

    script_version:
      validated.script_version,

    title_working:
      validated.title_working
  },

  summary: {
    requirement_count:
      validated.expected_requirement_count,

    resolved_reuse_count:
      reuseAssets.length,

    create_new_count:
      createAssets.length,

    human_review_count:
      humanReview.length,

    blocked_count:
      blocked.length
  },

  canonical_reuse_map:
    canonicalReuseMap,

  asset_creation_queue:
    assetCreationQueue,

  human_review_queue:
    humanReviewQueue,

  blocked_requirements:
    blockedRequirements,

  all_resolution_records:
    records,

  readiness_state:
    readinessState,

  dependency_breakdown: {
    approved_reuse_requirements:
      records.filter(item => item.requirement_origin === 'APPROVED_REUSE').length,
    approved_new_requirements:
      records.filter(item => item.requirement_origin === 'APPROVED_NEW').length,
    visual_tbd_requirements:
      records.filter(item => item.requirement_origin === 'TBD_DEPENDENCY' && item.requirement_type !== 'AUDIO').length,
    audio_tbd_requirements:
      records.filter(item => item.requirement_origin === 'TBD_DEPENDENCY' && item.requirement_type === 'AUDIO').length,
    unresolved_visual_tbd:
      records.filter(item => item.requirement_origin === 'TBD_DEPENDENCY' && item.requirement_type !== 'AUDIO' && item.resolution_status !== 'REUSE_EXISTING').length,
    unresolved_audio_tbd:
      records.filter(item => item.requirement_origin === 'TBD_DEPENDENCY' && item.requirement_type === 'AUDIO' && item.resolution_status !== 'REUSE_EXISTING').length
  },

  source_manifest_context:
    s5Ctx.source_manifest_context || null,

  governance: {
    agent_status:
      'REVIEW',

    human_approval_required:
      true,

    rule:
      'AGENT-006 may assess readiness but may not approve its own production-readiness manifest.'
  }
};

return [
  {
    json: {
      asset_resolution_run_id:
        validated.asset_resolution_run_id,

      production_manifest_id:
        validated.production_manifest_id,

      production_plan_run_id:
        validated.production_plan_run_id,

      episode_script_id:
        validated.episode_script_id,

      episode_code:
        validated.episode_code,

      script_version:
        validated.script_version,

      title_working:
        validated.title_working,

      requirement_count:
        validated.expected_requirement_count,

      resolved_reuse_count:
        reuseAssets.length,

      create_new_count:
        createAssets.length,

      human_review_count:
        humanReview.length,

      blocked_count:
        blocked.length,

      readiness_state:
        readinessState,

      readiness_manifest_json:
        readinessManifest,

      status:
        'REVIEW',

      agent_version:
        validated.agent_version,

      prompt_version:
        validated.prompt_version
    }
  }
];

const saved =
  $input.first().json;

const source =
  $('12 - Build Production Readiness Manifest')
    .first()
    .json;

let nextAction;

switch (
  source.readiness_state
) {

  case 'BLOCKED':

    nextAction =
      'Resolve the missing upstream-approved reusable assets before any generation begins.';

    break;

  case 'NEEDS_HUMAN_REVIEW':

    nextAction =
      'Review unresolved canonical asset mappings and decide whether each requirement should reuse an existing asset or become a newly approved asset.';

    break;

  case 'NEEDS_ASSET_CREATION':

    nextAction =
      'Create the approved new assets in the asset-creation queue, register them in the canonical asset registry, then rerun Agent-006.';

    break;

  case 'READY_FOR_HUMAN_APPROVAL':

    nextAction =
      'Human production review may now approve this readiness manifest for downstream generation.';

    break;

  default:

    nextAction =
      'Review Agent-006 output.';
}

const directorBrief =
`🧰 AGENT-006 asset resolution complete

Episode:
${source.episode_code}

Script:
${source.script_version}

Title:
${source.title_working}

Asset Resolution Run:
${source.asset_resolution_run_id}

Requirements checked:
${source.requirement_count}

Canonical assets ready for reuse:
${source.resolved_reuse_count}

Approved new assets still requiring creation:
${source.create_new_count}

Requirements needing human mapping review:
${source.human_review_count}

Blocked missing reusable assets:
${source.blocked_count}

Production readiness:
${source.readiness_state}

Next action:
${nextAction}

Manifest status:
REVIEW

AGENT-006 has not approved its own readiness decision.

The complete production-readiness manifest has been saved in Supabase.`;

return [
  {
    json: {
      production_readiness_manifest_id:
        saved.id || null,

      asset_resolution_run_id:
        source.asset_resolution_run_id,

      production_manifest_id:
        source.production_manifest_id,

      episode_code:
        source.episode_code,

      script_version:
        source.script_version,

      title_working:
        source.title_working,

      readiness_state:
        source.readiness_state,

      manifest_status:
